import pathlib,json,uuid,shutil
R=pathlib.Path(__file__).resolve().parents[1]
def write(name,value):
 p=R/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def uid(name):return str(uuid.uuid5(uuid.NAMESPACE_URL,'https://shiratama984-lab/smp/v1/'+name))
write('behavior_pack/manifest.json',{'format_version':2,'header':{'name':'SMP Chest Hub 0.1.0','description':'チェストUI・オークション・経済・ホーム・土地保護','uuid':uid('bp'),'version':[0,1,0],'min_engine_version':[1,21,80]},'modules':[{'type':'data','uuid':uid('data'),'version':[0,1,0]},{'type':'script','language':'javascript','entry':'scripts/main.js','uuid':uid('script'),'version':[0,1,0]}],'dependencies':[{'module_name':'@minecraft/server','version':'2.0.0'},{'module_name':'@minecraft/server-ui','version':'2.0.0'},{'uuid':uid('rp'),'version':[0,1,0]}]})
write('resource_pack/manifest.json',{'format_version':2,'header':{'name':'SMP Chest Hub — チェストUI','description':'54スロットの独自チェストメニューとアイコン','uuid':uid('rp'),'version':[0,1,0],'min_engine_version':[1,21,80]},'modules':[{'type':'resources','uuid':uid('resources'),'version':[0,1,0]}],'subpacks':[{'folder_name':'chest','name':'チェスト型UI','memory_tier':0},{'folder_name':'standard','name':'標準UI（互換モード）','memory_tier':1}]})
shutil.copyfile(R/'resource_pack/pack_icon.png',R/'behavior_pack/pack_icon.png')
write('behavior_pack/items/menu.json',{'format_version':'1.21.80','minecraft:item':{'description':{'identifier':'smp:menu','menu_category':{'category':'equipment'}},'components':{'minecraft:display_name':{'value':'§bSMPメニュー'},'minecraft:icon':'smp_menu','minecraft:max_stack_size':1,'minecraft:interact_button':'SMPメニューを開く','minecraft:use_modifiers':{'use_duration':0.1,'movement_modifier':1},'minecraft:use_animation':'bow'}}})
write('resource_pack/textures/item_texture.json',{'resource_pack_name':'smp_chest_hub','texture_name':'atlas.items','texture_data':{'smp_menu':{'textures':'textures/smp/menu'}}})
write('behavior_pack/recipes/menu.json',{'format_version':'1.20.10','minecraft:recipe_shapeless':{'description':{'identifier':'smp:menu_recipe'},'tags':['crafting_table'],'ingredients':[{'item':'minecraft:compass'},{'item':'minecraft:chest'}],'result':{'item':'smp:menu','count':1}}})
prefix='§0[SMP:CHEST]§r '
matched=f"(not ((#title_text - '{prefix}') = #title_text))"
def visible(expr):return [{'binding_name':'#title_text'},{'binding_type':'view','source_property_name':expr,'target_property_name':'#visible'}]
normal={'$title_panel':'common_dialogs.standard_title_label','$title_size':['100% - 14px',10],'$text_name':'#title_text','$title_text_binding_type':'none','$child_control':'server_form.long_form_panel','size':[225,200],'layer':2}
chest={'$title_panel':'smp_chest.title','$title_size':['100% - 14px',12],'$child_control':'smp_chest.content','size':[280,242],'layer':2,'bindings':visible(matched)}
write('resource_pack/ui/server_form.json',{'namespace':'server_form','long_form':{'type':'panel','size':['100%','100%'],'controls':[{'native@common_dialogs.main_panel_no_buttons':{**normal,'bindings':visible('(not '+matched+')')}},{'chest@common_dialogs.main_panel_no_buttons':chest}]}})
forms={'namespace':'smp_chest','title':{'type':'label','text':'#page_title','color':[1,1,1],'text_alignment':'center','bindings':[{'binding_name':'#title_text'},{'binding_type':'view','source_property_name':f"(#title_text - '{prefix}')",'target_property_name':'#page_title'}]},'content':{'type':'panel','size':[264,208],'controls':[{'background':{'type':'image','texture':'textures/smp/chest','size':['100%','100%'],'layer':0}},{'summary':{'type':'label','text':'#form_text','color':[0.08,0.1,0.13],'size':[248,26],'anchor_from':'top_middle','anchor_to':'top_middle','offset':[0,4],'font_scale_factor':0.75,'text_alignment':'center','layer':2,'bindings':[{'binding_name':'#form_text'}]}},{'grid':{'type':'grid','size':[252,168],'offset':[6,34],'anchor_from':'top_left','anchor_to':'top_left','grid_dimensions':[9,6],'grid_item_template':'smp_chest.slot','collection_name':'form_buttons','layer':3}}]},'slot@common.button':{'size':[28,28],'$pressed_button_name':'button.form_button_click','default_control':'normal','hover_control':'hover','pressed_control':'pressed','locked_control':'normal','controls':[{'normal':{'type':'image','texture':'textures/smp/slot','size':['100%','100%']}},{'hover':{'type':'panel','size':['100%','100%'],'controls':[{'highlight':{'type':'image','texture':'textures/smp/slot_hover','size':['100%','100%']}},{'tooltip':{'type':'custom','renderer':'hover_text_renderer','allow_clipping':False,'layer':30,'bindings':[{'binding_name':'#form_button_text','binding_name_override':'#hover_text','binding_type':'collection','binding_collection_name':'form_buttons'}]}}]}},{'pressed':{'type':'image','texture':'textures/smp/slot_pressed','size':['100%','100%']}},{'icon':{'type':'image','size':[22,22],'layer':4,'bindings':[{'binding_name':'#form_button_texture','binding_name_override':'#texture','binding_type':'collection','binding_collection_name':'form_buttons'},{'binding_name':'#form_button_texture_file_system','binding_name_override':'#texture_file_system','binding_type':'collection','binding_collection_name':'form_buttons'}]}}],'bindings':[{'binding_type':'collection_details','binding_collection_name':'form_buttons'},{'binding_name':'#form_button_text','binding_type':'collection','binding_collection_name':'form_buttons'},{'binding_type':'view','source_property_name':"(not (#form_button_text = ''))",'target_property_name':'#enabled'}]}}
write('resource_pack/ui/smp_chest.json',forms)
write('resource_pack/ui/_ui_defs.json',{'ui_defs':['ui/smp_chest.json']})
write('resource_pack/subpacks/standard/ui/server_form.json',{'namespace':'server_form','long_form':{'type':'panel','size':['100%','100%'],'controls':[{'native@common_dialogs.main_panel_no_buttons':normal}]}})
(R/'resource_pack/subpacks/chest').mkdir(parents=True,exist_ok=True);(R/'resource_pack/subpacks/chest/README.txt').write_text('Chest UI uses the main resource-pack definitions.\n')
print('Generated standalone SMP packs and 9x6 chest UI')
